-- Table: tests
DROP TABLE IF EXISTS "tests" CASCADE;
CREATE TABLE IF NOT EXISTS "tests" (
    "category" TEXT,
    "created_at" TIMESTAMPTZ,
    "id" INTEGER,
    "name" TEXT,
    "normal_max" TEXT,
    "normal_min" TEXT,
    "status" BOOLEAN,
    "unit" TEXT,
    PRIMARY KEY ("id")
);

ON CONFLICT DO NOTHING;
